  if (ckdEpi >= 90) colIdx = 4;
  else if (ckdEpi >= 70) colIdx = 3;
  else if (ckdEpi >= 50) colIdx = 2;
  else if (ckdEpi >= 30) colIdx = 1;
  else colIdx = 0;
