      if (ckdEpi >= 70) return { doseMg: 1e3, intervalHours: 12 };
      if (ckdEpi >= 50) return { doseMg: 1750, intervalHours: 24 };
      if (ckdEpi >= 30) return { doseMg: 1250, intervalHours: 24 };
      return { doseMg: 1e3, intervalHours: 24 };
